variable "audit_log_types" {
  type        = list(string)
  description = "Audit log types enabled on the folder for var.audit_service"
  default     = ["ADMIN_READ", "DATA_READ", "DATA_WRITE"]

  validation {
    condition     = length(setsubtract(var.audit_log_types, ["ADMIN_READ", "DATA_READ", "DATA_WRITE"])) == 0
    error_message = "var.audit_log_types must only contain ADMIN_READ, DATA_READ or DATA_WRITE"
  }

  validation {
    condition     = contains(var.audit_log_types, "ADMIN_READ")
    error_message = "var.audit_log_types must include ADMIN_READ"
  }
}

resource "google_folder_iam_audit_config" "all_services" {
  folder  = google_folder.main.name
  service = "allServices"

  dynamic "audit_log_config" {
    for_each = toset(var.audit_log_types)

    content {
      log_type = audit_log_config.value
    }
  }
}

variable "require_shielded_vm" {
  type        = bool
  description = "Whether to enforce the compute.requireShieldedVm organization policy on the folder"
  default     = true
}

resource "google_org_policy_policy" "require_shielded_vm" {
  count = var.require_shielded_vm ? 1 : 0

  name   = "${google_folder.main.name}/policies/compute.requireShieldedVm"
  parent = google_folder.main.name

  spec {
    inherit_from_parent = true

    rules {
      enforce = "TRUE"
    }
  }
}
